#include <arm_neon.h>
#include <dispatch/dispatch.h>
#include <stdint.h>

// Process a chunk of rows [r0, r1) of W (d,n) @ x (n,) -> xout (d,)
static void matmul_rows(float* xout, const float* x, const float* w,
                        int n, int r0, int r1) {
    const int n4 = n & ~3;
    for (int i = r0; i < r1; i++) {
        const float* wp = w + (size_t)i * n;
        float32x4_t acc0 = vdupq_n_f32(0.0f);
        float32x4_t acc1 = vdupq_n_f32(0.0f);
        int j = 0;
        for (; j < n4; j += 8) {
            float32x4_t w0 = vld1q_f32(wp + j);
            float32x4_t w1 = vld1q_f32(wp + j + 4);
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            acc0 = vfmaq_f32(acc0, w0, x0);
            acc1 = vfmaq_f32(acc1, w1, x1);
        }
        for (; j < n4; j += 4) {
            float32x4_t w0 = vld1q_f32(wp + j);
            float32x4_t x0 = vld1q_f32(x + j);
            acc0 = vfmaq_f32(acc0, w0, x0);
        }
        float32x4_t acc = vaddq_f32(acc0, acc1);
        float val = vaddvq_f32(acc);
        for (; j < n; j++) {
            val += wp[j] * x[j];
        }
        xout[i] = val;
    }
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    const int chunk = 8;
    const int nchunks = (d + chunk - 1) / chunk;
    if (nchunks <= 1) {
        matmul_rows(xout, x, w, n, 0, d);
        return;
    }
    dispatch_apply(nchunks, DISPATCH_APPLY_AUTO, ^(size_t c) {
        int r0 = (int)c * chunk;
        int r1 = r0 + chunk;
        if (r1 > d) r1 = d;
        matmul_rows(xout, x, w, n, r0, r1);
    });
}

